@   DISPLAY_STATE_STEP3              = 0x7f
@   DISPLAY_STATE_STEP4              = 0x80
@   CARD_ID_THUNDER_CRASH            = 0x16d7  (Thunder Crash)
@   CARD_ID_ENCHANTED_ARROW          = 0x14aa  (Enchanted Arrow)
@   CARD_ID_TOKEN_THANKSGIVING       = 0x1665  (Token Thanksgiving)
@   CARD_ID_TOKEN_FEASTEVIL          = 0x18dc  (Token Feastevil)
